<h1><?= te('Site safety plan') ?></h1><form class="card" method="get"><label><?= te('Project') ?><select name="job_id"><?php foreach($jobs as $job): ?><option value="<?= (int)$job['id'] ?>" <?= $jobId===(int)$job['id']?'selected':'' ?>><?= e($job['title']) ?></option><?php endforeach; ?></select></label><button class="btn"><?= te('Open project') ?></button></form>
<form class="card" method="post"><?= csrf_field() ?><input type="hidden" name="job_id" value="<?= $jobId ?>"><?php foreach(['access_instructions'=>'Site access instructions','emergency_contacts'=>'Emergency contacts','escalation_procedure'=>'Incident escalation procedure','site_posts'=>'Security posts and handover instructions'] as $key=>$label): ?><label><?= te($label) ?><?php if(can('recruiter')): ?><textarea name="<?= e($key) ?>" maxlength="8000" rows="4"><?= e($plan[$key]??'') ?></textarea><?php else: ?><p style="white-space:pre-wrap"><?= e($plan[$key]??'') ?></p><?php endif; ?></label><?php endforeach; ?><?php if(can('recruiter')): ?><button class="btn"><?= te('Save safety plan') ?></button><?php endif; ?></form>
